import{_ as p,a0 as s,w as h,s as a,ao as r,I as t,x as n,a1 as o,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"3個開源的Python Shell | LCTT x X-CMD","titleTemplate":false,"description":"3個開源的Python Shell | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"3個開源的Python Shell | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"3個開源的Python Shell | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150527 3 Open Source Python Shells","title":"3個開源的Python Shell","tag":"201506","desc":""},"relativePath":"201506/20150527 3 Open Source Python Shells.md","filePath":"[post].md"}'),P={name:"201506/20150527 3 Open Source Python Shells.md"};function u(y,l,m,d,T,w){const i=s("Link");return h(),a("div",null,[l[26]||(l[26]=r('<h1 id="_3個開源的python-shell" tabindex="-1">3個開源的Python Shell <a class="header-anchor" href="#_3個開源的python-shell" aria-label="Permalink to “3個開源的Python Shell”">​</a></h1><p>Python是一個高級、通用、結構化且強大的開源編程語言，廣泛用於各種編程工作。它擁有一個全動態類型系統和自動內存管理，與Scheme，Ruby，Perl和Tcl的十分相似，避免編譯型語言的許多複雜地方和難以理解。Python於1991年由Guido van Rossum創造，然後逐漸成長，流行。</p><p>Python是一個非常實用，而且流行的計算機編程語言。使用一個如Python這樣的解釋型語言的好處之一就是，可以藉助其交互的shell探索式地編程。你可以試着代碼，而不必專門寫一個腳本。但是Python shell也有一些侷限性。基本來説，有許多很漂亮的Python shell可選擇，都是在基礎shell上擴展的。他們每一個都提供了一個極好的交互性的Python 體驗。</p><h3 id="bpython" tabindex="-1">bpython <a class="header-anchor" href="#bpython" aria-label="Permalink to “bpython”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Programming/Screenshot-bpython.png" alt=""></p><p>對於Linux，BSD，OS X和Windows來説，bpython是一個不錯的Python解釋器的界面。</p><p>其想法是提供給用户所有的內置功能，很像現在的IDE（集成開發環境），但是是在一個簡單，輕量級的包裏，可以在終端窗口裏面運行。</p><p>bpython並不追求創造任何新的或者開創性的東西。相反，它聚集了一些簡潔的理念，關注於實用性和操作性。</p><p>功能包括：</p><ul><li>內置的語法高亮 - 使用Pygments排版你敲出的代碼，併合理配色</li><li>根據你的行為，顯示自動補全的建議</li><li>為任何Python函數列出所期望的參數 - 可以顯示你調用的任何函數的參數列表</li><li>“Rewind”功能會調出內存裏的最後一行代碼並重新執行</li><li>可以將你輸入的代碼送到pastebin</li><li>可以將你輸入的代碼保存到一個文件</li><li>自動縮進</li><li>支持Python 3</li></ul><hr>',11)),t("ul",null,[t("li",null,[l[1]||(l[1]=n("網址: ",-1)),o(i,{href:"http://www.bpython-interpreter.org/"},{default:e(()=>[...l[0]||(l[0]=[n("www.bpython-interpreter.org",-1)])]),_:1})]),l[2]||(l[2]=t("li",null,"開發者: Bob Farrell and contributors",-1)),l[3]||(l[3]=t("li",null,"證書: MIT License",-1)),l[4]||(l[4]=t("li",null,"版本號: 0.14.1",-1))]),l[27]||(l[27]=r('<h3 id="ipython" tabindex="-1">IPython <a class="header-anchor" href="#ipython" aria-label="Permalink to “IPython”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Programming/Screenshot-ipython.png" alt=""></p><p>IPython是Python shell的一個交互加強版。她提供了一個豐富的工具集合，幫助你交互式地充分利用Python。</p><p>IPython可以用來取代標準的Python shell，也可以與標準Python科學和數值處理工具配合，用做一個科學計算（如Matlab或者Mathematical）的完整工作環境。她支持動態對象內省，有限的輸入/輸出提示，一個宏系統，會話日誌，會話恢復，訪問完整的系統外殼，詳盡且彩色的追蹤報告，自動圓括號補全，自動引號補全和可嵌入其他Python程序。</p><p>功能包括：</p><ul><li>強大的交互Shell（基於終端或者Qt）</li><li>一個基於瀏覽器的記事本，支持代碼，富文本，數學表達式，內置圖表和其他富媒介。</li><li>支持交互式的數據可視化和使用GUI工具箱</li><li>靈活，嵌入式的解釋器可以加載進你自己的項目裏</li><li>易於使用，高效的並行運算工具</li></ul><hr>',7)),t("ul",null,[t("li",null,[l[6]||(l[6]=n("網址: ",-1)),o(i,{href:"http://ipython.org/"},{default:e(()=>[...l[5]||(l[5]=[n("ipython.org",-1)])]),_:1})]),l[7]||(l[7]=t("li",null,"開發者: The IPython Development Team",-1)),l[8]||(l[8]=t("li",null,"證書: BSD",-1)),l[9]||(l[9]=t("li",null,"版本號: 3.1",-1))]),l[28]||(l[28]=r('<h3 id="dreampie" tabindex="-1">DreamPie <a class="header-anchor" href="#dreampie" aria-label="Permalink to “DreamPie”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Programming/Screenshot-DreamPie.png" alt=""></p><p>DreamPie是一個為可靠性和趣味性設計的Python shell。</p><p>DreamPie可以用於任何Python解釋器（Jython，IronPython，PyPy）。</p><p>功能包括：</p><ul><li>一個新式的交互shell：窗口被分成歷史區域和代碼區域，歷史區域可以讓你看到之前的命令及其輸出，代碼區域是裏敲代碼的地方。這樣，你可以編輯任意多的代碼，就好像在你最喜歡的編輯器裏一樣，並且適當時候可以執行它。你也可以從其他地方複製代碼，編輯並馬上運行它</li><li>“只複製代碼”命令可以複製你想要的代碼，以便你可以把它存入一個文件。代碼已經用四個空格縮進進行格式化</li><li>自動補全屬性和文件名字</li><li>自動顯示函數參數和文檔</li><li>在結果歷史中保存你最近的結果，備以後用</li><li>可以自動摺疊很長的輸出，以便你可以專注於重要的地方</li><li>保存會話的歷史記錄為一個HTML文件，備以後查詢。你可以加載歷史文件到DreamPie裏，並且快速重複之前的命令。</li><li>自動添加圓括號與可選的引號，當你在函數與方法後按下空格鍵。例如，鍵入execfile後按下空格會提示execfile(&quot;fn&quot;)</li><li>支持交互的matplotlib繪圖</li><li>支持Python 2.5，Python 2.6，Python 3.1，Jython 2.5，IronPython 2.6和PyPy</li><li>難以置信的快速反應</li></ul><hr>',7)),t("ul",null,[t("li",null,[l[11]||(l[11]=n("網址: ",-1)),o(i,{href:"http://www.dreampie.org/"},{default:e(()=>[...l[10]||(l[10]=[n("www.dreampie.org",-1)])]),_:1})]),l[12]||(l[12]=t("li",null,"開發者: Noam Yorav-Raphael",-1)),l[13]||(l[13]=t("li",null,"證書: GNU GPL v3",-1)),l[14]||(l[14]=t("li",null,"版本號: 1.2.1",-1))]),l[29]||(l[29]=t("hr",null,null,-1)),t("p",null,[l[16]||(l[16]=n("via: ",-1)),o(i,{href:"http://www.linuxlinks.com/article/20150523032756576/PythonShells.html"},{default:e(()=>[...l[15]||(l[15]=[n("http://www.linuxlinks.com/article/20150523032756576/PythonShells.html",-1)])]),_:1})]),t("p",null,[l[19]||(l[19]=n("作者：Frazer Kline 譯者：",-1)),o(i,{href:"https://github.com/wi-cuckoo"},{default:e(()=>[...l[17]||(l[17]=[n("wi-cuckoo",-1)])]),_:1}),l[20]||(l[20]=n(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:e(()=>[...l[18]||(l[18]=[n("wxy",-1)])]),_:1})]),t("p",null,[l[23]||(l[23]=n("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...l[21]||(l[21]=[n("LCTT",-1)])]),_:1}),l[24]||(l[24]=n(" 原創翻譯，",-1)),o(i,{href:"https://linux.cn/"},{default:e(()=>[...l[22]||(l[22]=[n("Linux中國",-1)])]),_:1}),l[25]||(l[25]=n(" 榮譽推出",-1))]),l[30]||(l[30]=t("hr",null,null,-1))])}const b=p(P,[["render",u]]);export{g as __pageData,b as default};
